async function demandPage(){let d=await api('/api/demand?metric=reservations&'+qs()),m=new Map(d.map(x=>[x.weekday+'-'+x.hour,x.value])),vals=d.map(x=>x.value).sort((a,b)=>a-b),med=vals[Math.floor(vals.length/2)]||1;return `<div class="card"><h3>Demanda contextual · día × hora</h3><p>Cada celda se compara visualmente con la mediana del contexto filtrado. La clasificación analítica usa mínimo 8 comparables: &lt;60% rojo, 60–89% amarillo, 90–124% verde, ≥125% azul.</p><div class="heat"><b></b>${[11,13,16,18,20,22].map(h=>`<b>${h}:00</b>`).join('')}${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map((day,i)=>`<b>${day}</b>${[11,13,16,18,20,22].map(h=>{let v=m.get(i+'-'+h);let c=v==null?'gray':v/med<.6?'red':v/med<.9?'yellow':v/med<1.25?'green':'blue';return `<div class="cell ${c}">${v??'—'}</div>`}).join('')}`).join('')}</div></div>`}
