const escapeChat=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
async function sendChat(e){e?.preventDefault();let input=$('#chatInput'),q=input.value.trim();if(!q||S.chatPending)return;let m=$('#messages'),launcher=$('#chatFab'),submit=$('#chatForm button[type="submit"]'),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);S.chatPending=true;launcher.classList.add('thinking');submit.disabled=true;m.innerHTML+=`<div class="msg user">${escapeChat(q)}</div><div id="thinking" class="msg bot thinking" role="status">WOM 3000 está consultando los datos…</div>`;input.value='';m.scrollTop=m.scrollHeight;try{let start=pageChrome.filters.querySelector('#start'),end=pageChrome.filters.querySelector('#end'),location=pageChrome.filters.querySelector('#location'),room=pageChrome.filters.querySelector('#room'),context={page:S.page,start:start?.value||null,end:end?.value||null,location_id:location?.value||null,room_id:room?.value||null},r=await api('/api/assistant/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,session_id:S.sessionId,context}),signal:controller.signal});$('#thinking')?.remove();$('#chatProvider').textContent=`${r.provider==='local'?'Motor interno':r.provider||'Fallback local'} · ${r.tool||r.status} · solo lectura · Datos DEMO`;let extra=r.chart?chatChart(r.chart):'';m.innerHTML+=`<div class="msg bot">${escapeChat(r.answer)}${extra}</div>`}catch(err){$('#thinking')?.remove();let text=err.name==='AbortError'?'La consulta ha tardado demasiado y se ha cancelado. Puedes volver a intentarlo.':'No he podido consultar ese dato ahora mismo. Puedes volver a intentarlo.';m.innerHTML+=`<div class="msg bot error">${text}</div>`;console.error('WOM 3000 query failed',err)}finally{clearTimeout(timer);S.chatPending=false;launcher.classList.remove('thinking');submit.disabled=false;m.scrollTop=m.scrollHeight;input.focus()}}
