function bindFinanceTable(kind){let host=document.querySelector(`.finance-table-app[data-table="${kind}"]`),state=S.financeTables[kind];if(!host)return;host.querySelector('[data-toggle-detail-filters]').onclick=e=>{let panel=host.querySelector('.detail-filters'),open=panel.classList.toggle('hidden')===false;e.currentTarget.setAttribute('aria-expanded',open)};let runSearch=()=>{state.filters.search=host.querySelector('[data-detail-search]').value.trim();state.page=1;loadFinanceTable(kind)};host.querySelector('[data-detail-search-run]').onclick=runSearch;host.querySelector('[data-detail-search]').onkeydown=e=>{if(e.key==='Enter')runSearch()};host.querySelector('[data-apply-detail]').onclick=()=>{host.querySelectorAll('[data-detail-filter]').forEach(x=>state.filters[x.dataset.detailFilter]=x.value);state.page=1;loadFinanceTable(kind)};host.querySelector('[data-clear-detail]').onclick=()=>{state.filters={};state.page=1;loadFinanceTable(kind)};host.querySelectorAll('[data-detail-sort]').forEach(x=>x.onclick=()=>{state.direction=state.sort===x.dataset.detailSort&&state.direction==='asc'?'desc':'asc';state.sort=x.dataset.detailSort;state.page=1;loadFinanceTable(kind)});host.querySelectorAll('[data-detail-page]').forEach(x=>x.onclick=()=>{state.page=+x.dataset.detailPage;loadFinanceTable(kind)});host.querySelector('[data-detail-size]').onchange=e=>{state.page_size=+e.target.value;state.page=1;loadFinanceTable(kind)}}
