async function insightsV290(){let[a,s]=await Promise.all([api('/api/alerts'),api('/api/alerts/engine/status')]),c=s.counts,type=x=>x.evidence.event_type||'A VIGILAR',tone=x=>type(x)==='EVOLUCIÓN POSITIVA'?'positive':type(x)==='REQUIERE ATENCIÓN'?'critical':type(x)==='INSIGHT'?'info':'warning';return `<section class="card"><span class="badge">DATOS DEMO V3 · ALGORITMO REAL</span><h2>¿Qué merece atención?</h2><p>Este apartado detecta automáticamente situaciones relevantes a partir de los datos de WOM. Los hechos proceden de cálculos deterministas; no se inventan causas.</p><div class="alert-summary"><b>${c.attention} requieren atención</b><b>${c.watch} a vigilar</b><b>${c.positive} evoluciones positivas</b><b>${c.insight} insights</b><b>${c.resolved} resueltas</b></div><p>Última evaluación: ${s.last_run.evaluated_at?new Date(s.last_run.evaluated_at).toLocaleString('es-ES'):'sin ejecutar'} · Próximo resumen diario: ${new Date(s.next_daily_summary).toLocaleString('es-ES')}</p><button id="evaluateAlerts">Evaluar ahora</button></section><section class="card"><h2>Eventos detectados</h2>${a.map(x=>`<article class="card notice ${tone(x)} ${x.status==='RESOLVED'?'resolved':''}"><div><span class="badge">${type(x)}</span> <span class="badge">${x.status}</span> <span class="badge">${x.evidence.source_module||x.category}</span></div><h3>${x.title}</h3><p>${x.explanation}</p><div class="grid2"><div><small>Actual</small><b>${num(x.current_value)}</b></div><div><small>Referencia</small><b>${num(x.baseline_value)}</b></div></div><p><b>Diferencia:</b> ${num(x.evidence.absolute_difference??(x.current_value-x.baseline_value))} · ${num(x.deviation)} %</p><details><summary>¿Por qué aparece?</summary><p>Detector: ${x.evidence.detector_id||'histórico'}. Muestra: ${x.evidence.sample_size||'—'}. Referencia: ${x.evidence.reference_period||x.evidence.baseline||'comparable interna'}.</p><p>Los datos disponibles no permiten determinar la causa del fenómeno.</p></details><button data-alert="${x.id}" ${x.seen?'disabled':''}>${x.seen?'Vista':'Marcar como vista'}</button></article>`).join('')||'<p>No hay situaciones que superen los cinco controles del motor.</p>'}</section><details class="card"><summary>¿Cómo se generan las alertas?</summary><p>El sistema compara datos actuales con referencias equivalentes y aplica cinco controles: calidad, comparabilidad, evidencia, relevancia y deduplicación. Solo publica eventos respaldados por una muestra suficiente.</p></details>`}
insights=insightsV290;

function expenseEntryForm(categories,locations){return `<form id="manualExpense" class="manual-expense"><fieldset class="expense-type"><legend>¿Qué tipo de gasto quieres registrar?</legend><label><input type="radio" name="expense_type" value="one_off" checked> Puntual</label><label><input type="radio" name="expense_type" value="recurring"> Recurrente</label></fieldset><label>Concepto<input name="concept" required minlength="2"></label><label>Importe<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Categoría<select name="category_id" required>${categories.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label>Ámbito / local<select name="location_id"><option value="">Corporativo / sin asignar</option>${locations.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label><span class="expense-date-label">Fecha</span><input name="expense_date" type="date" required></label><label>Notas<textarea name="notes"></textarea></label><div class="recurrence-fields hidden"><label>Periodicidad<select name="periodicity"><option value="monthly">Mensual</option><option value="quarterly">Trimestral</option><option value="annual">Anual</option><option value="custom">Personalizada</option></select></label><div class="custom-recurrence hidden"><span>Cada</span><input name="custom_interval" type="number" min="1" value="1"><select name="custom_unit"><option value="days">días</option><option value="weeks">semanas</option><option value="months">meses</option><option value="years">años</option></select></div></div><button class="primary">Guardar gasto</button><div id="expenseResult" aria-live="polite"></div></form>`}
