dashboard=dashboardUX;finance=financeUX;locations=locationsUX;rooms=roomsUX;
let bindDynamicUX=bindDynamic;bindDynamic=function(){bindDynamicUX();document.querySelectorAll('[data-page-link]').forEach(b=>b.onclick=()=>{S.page=b.dataset.pageLink;render()});let add=$('#financeAddExpense'),panel=$('#financeExpensePanel'),close=$('#closeFinanceExpense');if(add&&panel)add.onclick=()=>{panel.classList.remove('hidden');panel.scrollIntoView({behavior:'smooth'})};if(close&&panel)close.onclick=()=>panel.classList.add('hidden')};

async function init(){let[loc,rooms,range]=await Promise.all([api('/api/locations'),api('/api/rooms'),api('/api/data-range')]);S.dataRange=range;S.allRooms=rooms;$('#location').innerHTML+=loc.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');populateRooms(rooms);$('#nav').innerHTML=pages.map(x=>`<button data-page="${x[0]}">${x[1]}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;render()});document.querySelectorAll('.segments button').forEach(b=>b.onclick=async()=>{S.mode=b.dataset.mode;S.fallback=false;await setPeriod();render()});$('#prevPeriod').onclick=()=>shift(-1);$('#nextPeriod').onclick=()=>shift(1);$('#currentPeriod').onclick=async()=>{S.anchor=new Date();S.fallback=false;await setPeriod();render()};$('#reset').onclick=async()=>{$('#location').value='';$('#room').value='';populateRooms(rooms);S.mode='month';S.anchor=new Date();S.fallback=false;await setPeriod();await useLatestIfInitialPeriodIsEmpty();render()};$('#refresh').onclick=render;$('#location').onchange=()=>{$('#room').value='';populateRooms(rooms);render()};$('#room').onchange=render;['start','end'].forEach(x=>$('#'+x).onchange=()=>{S.mode='custom';S.fallback=false;if(validDates()){$('#periodLabel').textContent=`${humanDate($('#start').value)} — ${humanDate($('#end').value)}`;document.querySelectorAll('.segments button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='custom'));render()}});$('#chatFab').onclick=()=>{$('#chatPanel').classList.remove('hidden');$('#chatPanel').classList.remove('minimized');updateAssistantStatus();$('#chatInput').focus()};$('#chatClose').onclick=()=>$('#chatPanel').classList.add('hidden');$('#chatMin').onclick=()=>$('#chatPanel').classList.toggle('minimized');$('#chatNew').onclick=()=>{S.sessionId=crypto.randomUUID();$('#messages').innerHTML='<div class="msg bot">Nueva conversación. Mantengo el periodo, local y sala visibles como contexto.</div>'};$('#chatForm').onsubmit=sendChat;$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChat(e)}};document.querySelectorAll('[data-chat-suggestion]').forEach(b=>b.onclick=()=>{$('#chatInput').value=b.dataset.chatSuggestion;sendChat()});showWomWelcome();updateAssistantStatus();await setPeriod();await useLatestIfInitialPeriodIsEmpty();render()}
async function shift(n){if(S.mode==='week')S.anchor.setDate(S.anchor.getDate()+7*n);else if(S.mode==='month')S.anchor.setMonth(S.anchor.getMonth()+n);else if(S.mode==='year')S.anchor.setFullYear(S.anchor.getFullYear()+n);else return;S.fallback=false;await setPeriod();render()}init();
